function mvErr(e,fb){const s=String(e&&e.message||e||'');return /no_key|503/.test(s)?'영화 검색 키가 아직 연결되지 않았어요.':/PGRST202|404|movie_list|Could not find/.test(s)?'영화관 서버 준비 중이에요.':fb}
function mvSel(id,cur_){const o=['<option value="">별점</option>'];for(let v=5;v>=.5;v-=.5)o.push(`<option value="${v}"${cur_!=null&&Number(cur_)==v?' selected':''}>★ ${v.toFixed(1)}</option>`);if(cur_!=null)o.push('<option value="del">지우기</option>');return`<select onchange="mvRate(${id},this.value,this)" aria-label="별점" style="font-size:13px;padding:4px">${o.join('')}</select>`}
