async function tvInfo(L,id){try{const r=await fetch('https://www.youtube.com/oembed?format=json&url='+encodeURIComponent('https://www.youtube.com/watch?v='+id));if(r.status==401||r.status==403||r.status==404){L.bad[id]=1;return}if(!r.ok)throw 0;const j=await r.json();L.t[id]=String(j.title||id)}catch(e){L.t[id]='영상 '+(L.ids.indexOf(id)+1)}}
