const RUN_MS=230;
function runnersStep(t){
  npcs.forEach(n=>{
    if(!n.run)return;
    if(n.mv&&t-n.mv.a>=RUN_MS){n.x=n.mv.tx;n.y=n.mv.ty;n.mv=null}
    if(n.mv||busy||dlg||modal)return;
    const nt=TRACK[(n.ti+1)%TRACK.length];
    if(nt[0]==px&&nt[1]==py)return;
    if(mv&&mv.tx==nt[0]&&mv.ty==nt[1])return;
    if(npcs.some(o=>o!==n&&((o.x==nt[0]&&o.y==nt[1])||(o.mv&&o.mv.tx==nt[0]&&o.mv.ty==nt[1]))))return;
    n.dir=Math.max(0,DV.findIndex(d=>d[0]==nt[0]-n.x&&d[1]==nt[1]-n.y));
    n.mv={a:t,fx:n.x,fy:n.y,tx:nt[0],ty:nt[1]};n.ti=(n.ti+1)%TRACK.length;
  });
}

